R["cb20-checkpoint-stack"] = "#include <stdio.h>\n#define SCAP 16\nstatic int st[SCAP];\nstatic int stop = 0;\nvoid stack_clear(void) { stop = 0; }\nint stack_push(int v) {\n    if (stop == SCAP) return 0;\n    st[stop++] = v;\n    return 1;\n}\nint stack_pop(int *out) {\n    if (out == NULL || stop == 0) return 0;\n    *out = st[--stop];\n    return 1;\n}\nint stack_size(void) { return stop; }\nint stack_top(int *out) {\n    if (out == NULL || stop == 0) return 0;\n    *out = st[stop - 1];\n    return 1;\n}\nint main(void) { return 0; }";
