R["cb21-binary-search"] = "#include <stdio.h>\nint binary_search_cj(const int *a, int n, int t) {\n    int lo = 0, hi = n - 1;\n    while (lo <= hi) {\n        int mid = lo + (hi - lo) / 2;\n        if (a[mid] == t) return mid;\n        if (a[mid] < t) lo = mid + 1;\n        else hi = mid - 1;\n    }\n    return -1;\n}\nint main(void) { return 0; }";
