R["cb21-selection-sort"] = "#include <stdio.h>\nvoid selection_sort(int *a, int n) {\n    for (int i = 0; i < n - 1; i++) {\n        int min = i;\n        for (int j = i + 1; j < n; j++)\n            if (a[j] < a[min]) min = j;\n        int t = a[i]; a[i] = a[min]; a[min] = t;\n    }\n}\nint main(void) { return 0; }";
