R["cb21-insertion-sort"] = "#include <stdio.h>\nvoid insertion_sort(int *a, int n) {\n    for (int i = 1; i < n; i++) {\n        int key = a[i];\n        int j = i - 1;\n        while (j >= 0 && a[j] > key) {\n            a[j + 1] = a[j];\n            j--;\n        }\n        a[j + 1] = key;\n    }\n}\nint main(void) { return 0; }";
