R["cb21-median-nomutate"] = "#include <stdio.h>\nvoid insertion_sort(int *b, int n) {\n    for (int i = 1; i < n; i++) {\n        int key = b[i];\n        int j = i - 1;\n        while (j >= 0 && b[j] > key) { b[j + 1] = b[j]; j--; }\n        b[j + 1] = key;\n    }\n}\ndouble median(const int *a, int n) {\n    int buf[64];\n    for (int i = 0; i < n; i++) buf[i] = a[i];\n    insertion_sort(buf, n);\n    if (n % 2 == 1) return (double)buf[n / 2];\n    return (buf[n / 2 - 1] + buf[n / 2]) / 2.0;\n}\nint main(void) { return 0; }";
W["cb21-median-nomutate"] = "#include <stdio.h>\nvoid insertion_sort(int *b, int n) {\n    for (int i = 1; i < n; i++) {\n        int key = b[i];\n        int j = i - 1;\n        while (j >= 0 && b[j] > key) { b[j + 1] = b[j]; j--; }\n        b[j + 1] = key;\n    }\n}\ndouble median(const int *a, int n) {\n    int buf[64];\n    for (int i = 0; i < n; i++) buf[i] = a[i];\n    insertion_sort(buf, n);\n    if (n % 2 == 1) return (double)buf[n / 2 + 1];\n    return (buf[n / 2 - 1] + buf[n / 2]) / 2.0;\n}\nint main(void) { return 0; }";
R["cb21-checkpoint-range"] = "#include <stdio.h>\nvoid sort_asc(int *a, int n) {\n    for (int i = 1; i < n; i++) {\n        int key = a[i];\n        int j = i - 1;\n        while (j >= 0 && a[j] > key) { a[j + 1] = a[j]; j--; }\n        a[j + 1] = key;\n    }\n}\nint in_range(const int *sorted_a, int n, int lo, int hi) {\n    int c = 0;\n    for (int i = 0; i < n; i++) {\n        if (sorted_a[i] > hi) break;\n        if (sorted_a[i] >= lo) c++;\n    }\n    return c;\n}\nint main(void) { return 0; }";
